    {
      "id": "R1",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "인물들의 견해가 아니라 두 음악의 특성을 특정 조성에 얽매이는지라는 동일한 기준으로 비교하므로 대조이다."
    },
    {
      "id": "R2",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "다장조의 으뜸음과 음 배열 규칙이 조성 음악의 위계질서를 보여 주는 구체적인 사례이므로 7번에 해당한다."
    },
    {
      "id": "R3",
      "type": "CONDITION",
      "otherName": "",
      "reason": "음계의 규칙에서 벗어난 음이 포함되는 경우 불협화음으로 취급된다는 판별 조건을 제시하므로 11번에 해당한다."
    },
    {
      "id": "R4",
      "type": "PROCESS",
      "otherName": "",
      "reason": "으뜸화음으로 시작한 다음 다른 화음들을 거치는 차례를 제시하므로 13번에 해당한다."
    },
    {
      "id": "R5",
      "type": "PROCESS",
      "otherName": "",
      "reason": "버금딸림화음과 딸림화음을 거친 뒤 으뜸화음으로 돌아오는 진행 순서이므로 13번에 해당한다."
    },
    {
      "id": "R6",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "다장조의 구체적인 화음 진행이 조성 음악의 선율 흐름이 미리 정해져 있다는 일반적 성질을 예시하므로 7번에 해당한다."
    },
    {
      "id": "R7",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "두 음악에서 으뜸음 중심의 위계질서가 존재하는지 여부를 비교하므로 대상의 특성에 관한 대조이다."
    },
    {
      "id": "R8",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "조성 음계와 12음 음렬을 장ㆍ단조의 경계가 명확한지라는 동일한 기준에서 대비한다."
    },
    {
      "id": "R9",
      "type": "CAUSE",
      "otherName": "",
      "reason": "반음 간격의 조밀한 배열이 조성 경계를 모호하게 만드는 실제 음악적 작용을 설명하므로 10번에 해당한다."
    },
    {
      "id": "R10",
      "type": "CAUSE",
      "otherName": "",
      "reason": "조성 경계의 모호함이 장조와 단조가 공존하는 듯한 인상을 발생시키므로 10번에 해당한다."
    },
    {
      "id": "R11",
      "type": "CAUSE",
      "otherName": "",
      "reason": "장ㆍ단조가 공존하는 듯한 인상이 무질서하다는 인식을 낳았다는 실제 인식 형성의 인과 관계이다."
    },
    {
      "id": "R12",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 음악이 무질서하게 받아들여졌지만 실제 의도는 새로운 질서를 마련하는 것이었다는 양면성을 제시하므로 5번에 해당한다."
    },
    {
      "id": "R13",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "음들의 내재적 관계에 기초한 새 형식이라는 구상을 유기적 통일성과 응집력의 원리로 상세히 풀므로 7번에 해당한다."
    },
    {
      "id": "R14",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "곡을 유기체로 완성하는 조건으로 제시된 응집력의 뜻을 음들 사이의 내적 결속으로 풀이하므로 8번에 해당한다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "유사성의 반복으로 응집력이 실현된다는 원리에서 반복될수록 응집력이 강화된다는 설명을 도출하므로 9번에 해당한다."
    },
    {
      "id": "R16",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "유사성의 반복으로 형성되는 응집력을 바탕으로 보편적 음악 질서를 이루려 하므로 수단과 목적의 관계이다."
    },
    {
      "id": "R17",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "음악적 경험을 일상적 경험이 의식의 지향성을 통해 구성된다는 설명의 예로 제시하므로 7번에 해당한다."
    },
    {
      "id": "R18",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "판단 중지의 의미를 자연적 태도에서 현상학적 태도로의 전환으로 풀이하므로 8번에 해당한다."
    },
    {
      "id": "R19",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "경험이 지향성을 통해 구성된다는 현상학의 원리를 조성 음악의 화음에 가져다 쓰므로 6번에 해당한다."
    },
    {
      "id": "R20",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "판단 중지와 현상학적 환원의 원리를 쇤베르크의 조성 질서 극복에 적용하므로 6번에 해당한다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "판단 중지를 통해 보편적 음악 질서를 확립했다는 해석이 음악의 본질에 접근했다는 평가를 뒷받침하므로 9번에 해당한다."
    },
    {
      "id": "R22",
      "type": "INTERPRETATION",
      "otherName": "",
      "reason": "레보비츠가 쇤베르크의 보편적 질서 추구를 현상학의 판단 중지라는 틀로 읽으므로 1번의 해석에 해당한다."
    },
    {
      "id": "R23",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "범조성과 현상학적 환원의 괴리를 제시하여 레보비츠의 긍정적 해석을 반박하므로 1번의 비판에 해당한다."
    },
    {
      "id": "R24",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "모든 전제를 중지하려는 현상학과 새로운 규범을 세운 쇤베르크의 입장을 나란히 비교하므로 1번의 관점 차이에 해당한다."
    },
    {
      "id": "R25",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "새 규범을 제시했다는 사실이 모든 전제를 중지하는 현상학적 환원과 괴리된다는 판단의 근거이므로 9번에 해당한다."
    },
    {
      "id": "R26",
      "type": "INTERPRETATION",
      "otherName": "",
      "reason": "모든 음의 동등한 지위라는 원리를 글쓴이가 현상학적 관점에서 새로운 규범으로 읽어 내므로 해석에 해당한다."
    },
    {
      "id": "R27",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "평균율이 음향적 가능성의 극히 일부만 표준화했다는 사실이 이를 물리적 제약으로 판단하는 근거이므로 9번에 해당한다."
    },
    {
      "id": "R28",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "아도르노의 명제를 인용하여 음악 재료에 문화적 맥락이 응축되어 있다는 설명을 뒷받침하므로 9번에 해당한다."
    },
    {
      "id": "R29",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "평균율이라는 전통적 재료를 유지한 태도를 전통적인 물감을 고수하는 태도에 빗대어 구체적으로 풀므로 7번에 해당한다."
    },
    {
      "id": "R30",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "음악 재료 자체에 문화적 맥락이 담긴다는 설명이 평균율의 수용을 전통적 재료의 고수로 평가하는 근거이므로 9번에 해당한다."
    },
    {
      "id": "R31",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "미시적 직관을 중시하는 후설과 거시적 구조에 치중한 쇤베르크의 관점을 비교하므로 1번의 관점 차이에 해당한다."
    },
    {
      "id": "R32",
      "type": "CAUSE",
      "otherName": "",
      "reason": "거시적 구조로만 음악을 조망한 것이 개별 음의 미시적 체험을 간과하게 했다는 작용 관계이므로 10번에 해당한다."
    },
    {
      "id": "R33",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "현상학적 잔여는 현상 그 자체여야 한다는 이론적 기준을 쇤베르크의 음악에 적용하므로 6번에 해당한다."
    },
    {
      "id": "R34",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "순수 현상에 이르지 못했다는 점에서 현상학적 잔여 개념과 어긋난다는 판단이 도출되므로 9번에 해당한다."
    },
    {
      "id": "R35",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "현상학과의 괴리에 대한 논의가 규범과 재료의 전제 문제에서 미시적 체험과 현상학적 잔여 문제로 확대되므로 3번에 해당한다."
    },
    {
      "id": "R36",
      "type": "CRITIQUE",
      "otherName": "",
      "reason": "유지된 전제와 거시적 구조 편중을 들어 12음 기법을 현상학적 환원으로 평가한 레보비츠의 해석을 반박하므로 1번의 비판에 해당한다."
    }
  ]
}

